function validate([primeFactors]) {
  if (!Number.isInteger(primeFactors)) return 'primeFactors must be a whole number.';
  if (primeFactors < 1 || primeFactors > 1e9) return 'primeFactors must be between 1 and 10^9.';
  return null;
}

