function maxNiceDivisors(primeFactors) {
  const MOD = 1000000007n;
  const power = (base, exponent) => {
    let result = 1n;
    while (exponent > 0) {
      if (exponent % 2 === 1) {
        result = result * base % MOD;
      }
      base = base * base % MOD;
      exponent = Math.floor(exponent / 2);
    }
    return result;
  };

  if (primeFactors <= 3) {
    return primeFactors;
  }
  const threes = Math.floor(primeFactors / 3);
  const remainder = primeFactors % 3;
  let product;
  if (remainder === 0) {
    product = power(3n, threes);
  } else if (remainder === 1) {
    product = power(3n, threes - 1) * 4n % MOD;
  } else {
    product = power(3n, threes) * 2n % MOD;
  }
  return Number(product);
}

