function maxNiceDivisors(primeFactors) {
  // best[k]: the largest product of positive integers that add up to k (one part alone is allowed).
  const best = [1n];
  for (let k = 1; k <= primeFactors; k++) {
    best[k] = 0n;
    for (let part = 1; part <= k; part++) {
      const product = BigInt(part) * best[k - part];
      if (product > best[k]) best[k] = product;
    }
  }
  return Number(best[primeFactors] % 1000000007n);
}

